CREATE TABLE `membership_data_scopes` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`membership_id` CHAR(36) CHARACTER SET ascii NOT NULL,`scope_type` ENUM('own','team','workspace','organization') NOT NULL,`scope_key` VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NULL,`team_id` CHAR(36) CHARACTER SET ascii NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_membership_scope_key`(`membership_id`,`scope_key`),KEY `idx_membership_scope_workspace`(`workspace_id`,`membership_id`),KEY `idx_membership_scope_team`(`team_id`,`membership_id`),CONSTRAINT `fk_membership_scopes_membership` FOREIGN KEY(`membership_id`) REFERENCES `memberships`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_membership_scopes_workspace` FOREIGN KEY(`workspace_id`) REFERENCES `workspaces`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_membership_scopes_team` FOREIGN KEY(`team_id`) REFERENCES `teams`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_membership_scopes_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
